<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Grid, Briefcase, Upload, User, Setting, Tickets, Search, Plus, ArrowRight, SwitchButton, Download, CircleCheck, Lock, Refresh } from '@element-plus/icons-vue'
import StudentDetail from './StudentDetail.vue'
import RecommendDialog from './RecommendDialog.vue'
import { api, download, educations, experiences, salary, time } from './api'
type View = 'dashboard' | 'jobs' | 'imports' | 'students' | 'users' | 'audit'
const me = ref<any>(null), booting = ref(true), view = ref<View>('dashboard'), loading = ref(false), busy = ref(false)
const loginForm = ref({ username: '', password: '' }), loginError = ref('')
const nav = [{ key: 'dashboard', label: '工作概览', icon: Grid }, { key: 'jobs', label: '共享岗位库', icon: Briefcase }, { key: 'imports', label: 'Excel 导入', icon: Upload }, { key: 'students', label: '学员与跟进', icon: User }]
const title = computed(() => ({ dashboard: '工作概览', jobs: '共享岗位库', imports: 'Excel 岗位导入', students: '学员与跟进', users: '顾问管理', audit: '操作日志' }[view.value]))
const dashboard = ref<any>({ jobs: 0, active_jobs: 0, students: 0, recommendations: 0, reminders: [] })
const jobs = ref<any[]>([]), jobTotal = ref(0), jobPage = ref(1)
const filters = ref<any>({ q: '', city: '', education: '', experience: '', status: '有效', salary_min: undefined })
const students = ref<any[]>([]), studentTotal = ref(0), studentPage = ref(1), studentQ = ref('')
const batches = ref<any[]>([]), batchTotal = ref(0), batchPage = ref(1), batch = ref<any>(null), batchFilter = ref('全部')
const accounts = ref<any[]>([]), logs = ref<any[]>([]), logTotal = ref(0), logPage = ref(1)
const studentId = ref<number | null>(null), studentDrawer = ref(false), detailKey = ref(0)
const handlingFollowup = ref<number | null>(null)
const jobDrawer = ref(false), selectedJob = ref<any>(null), jobEditing = ref(false), jobForm = ref<any>({})
const recommendDialog = ref(false), recommendationTarget = ref<any>(null)
const studentDialog = ref(false), editingStudent = ref<number | null>(null), studentForm = ref<any>({})
const userDialog = ref(false), userForm = ref({ username: '', name: '', password: '' })
const passwordDialog = ref(false), passwordUser = ref<any>(null), newPassword = ref('')
const previewRows = computed(() => batch.value?.rows.filter((r: any) => batchFilter.value === '全部' || r.state === batchFilter.value) || [])
const previewPage = ref(1)
const shownRows = computed(() => previewRows.value.slice((previewPage.value - 1) * 20, previewPage.value * 20))
async function run(fn: () => Promise<void>) { try { await fn() } catch (e: any) { ElMessage.error(e.message || '操作失败') } }
async function login() {
  loginError.value = ''; busy.value = true
  try { me.value = await api('/auth/login', { method: 'POST', body: JSON.stringify(loginForm.value) }); loginForm.value.password = ''; await reload() } catch (e: any) { loginError.value = e.message } finally { busy.value = false }
}
async function logout() { await run(async () => { await api('/auth/logout', { method: 'POST' }); clearSession() }) }
function clearSession() { recommendDialog.value = false; recommendationTarget.value = null; me.value = null; jobs.value = []; students.value = []; batch.value = null; batches.value = []; accounts.value = []; logs.value = []; dashboard.value = { jobs: 0, active_jobs: 0, students: 0, recommendations: 0, reminders: [] }; selectedJob.value = null; jobForm.value = {}; studentForm.value = {}; userForm.value = { username: '', name: '', password: '' }; newPassword.value = ''; passwordUser.value = null; jobDrawer.value = false; studentDrawer.value = false; studentId.value = null; studentDialog.value = false; userDialog.value = false; passwordDialog.value = false; loginForm.value.password = ''; view.value = 'dashboard' }
const expired = () => { clearSession(); ElMessage.warning('登录已过期，请重新登录') }
onMounted(async () => {
  window.addEventListener('session-expired', expired)
  try { me.value = await api('/auth/me'); await reload() } catch { /* Show login if no active session. */ } finally { booting.value = false }
})
onUnmounted(() => window.removeEventListener('session-expired', expired))
async function loadJobs(reset = false) {
  if (reset) jobPage.value = 1
  const params = new URLSearchParams({ page: String(jobPage.value) })
  for (const [k, v] of Object.entries(filters.value)) if (v !== '' && v != null) params.set(k, String(v))
  const data = await api(`/jobs?${params}`); jobs.value = data.items; jobTotal.value = data.total
}
async function loadStudents(reset = false) { if (reset) studentPage.value = 1; const d = await api(`/students?q=${encodeURIComponent(studentQ.value)}&page=${studentPage.value}`); students.value = d.items; studentTotal.value = d.total }
async function loadBatches() { const d = await api(`/imports?page=${batchPage.value}`); batches.value = d.items; batchTotal.value = d.total }
async function loadLogs() { const d = await api(`/audit-logs?page=${logPage.value}`); logs.value = d.items; logTotal.value = d.total }
async function reload() {
  loading.value = true
  await run(async () => {
    if (view.value === 'dashboard') dashboard.value = await api('/dashboard')
    if (view.value === 'jobs') await loadJobs()
    if (view.value === 'imports') await loadBatches()
    if (view.value === 'students') await loadStudents()
    if (view.value === 'users') accounts.value = await api('/users')
    if (view.value === 'audit') await loadLogs()
  }); loading.value = false
}
async function handleReminder(row: any) {
  if (handlingFollowup.value !== null) return
  handlingFollowup.value = row.id
  await run(async () => {
    await api(`/students/${row.student_id}/followups/${row.id}/handle`, { method: 'POST' })
    dashboard.value.reminders = dashboard.value.reminders.filter((f: any) => f.id !== row.id)
    if (studentDrawer.value && studentId.value === row.student_id) detailKey.value++
    ElMessage.success('已标记为已处理')
    dashboard.value = await api('/dashboard')
  })
  handlingFollowup.value = null
}
async function navigate(key: string) { if (key !== 'jobs') recommendationTarget.value = null; view.value = key as View; await reload() }
async function browseJobsForStudent(student: any) {
  recommendationTarget.value = { id: student.id, name: student.name, education: student.education, major: student.major }
  studentDrawer.value = false
  filters.value = { q: '', city: '', education: '', experience: '', status: '有效', salary_min: undefined }
  jobPage.value = 1
  await navigate('jobs')
}
function recommendationSaved() { if (studentDrawer.value) detailKey.value++ }
async function searchJobs() { loading.value = true; await run(() => loadJobs(true)); loading.value = false }
async function resetFilters() { filters.value = { q: '', city: '', education: '', experience: '', status: '有效', salary_min: undefined }; await searchJobs() }
async function showJob(j: any) { await run(async () => { selectedJob.value = await api(`/jobs/${j.id}`); jobEditing.value = false; jobDrawer.value = true }) }
function editJob() { const { id, created_at, created_by, effective_status, ...data } = selectedJob.value; jobForm.value = { ...data }; jobEditing.value = true }
async function saveJob() { busy.value = true; await run(async () => { selectedJob.value = await api(`/jobs/${selectedJob.value.id}`, { method: 'PUT', body: JSON.stringify(jobForm.value) }); jobEditing.value = false; ElMessage.success('岗位已更新'); await loadJobs() }); busy.value = false }
async function uploadExcel(event: Event) {
  const input = event.target as HTMLInputElement, file = input.files?.[0]; if (!file) return
  if (file.size > 10 * 1024 * 1024) { ElMessage.error('文件不能超过 10MB'); input.value = ''; return }
  busy.value = true
  await run(async () => { const body = new FormData(); body.append('file', file); batch.value = await api('/imports/preview', { method: 'POST', body }); batchFilter.value = '全部'; previewPage.value = 1; await loadBatches(); ElMessage.success('校验完成，请检查预览后确认入库') })
  busy.value = false; input.value = ''
}
async function showBatch(row: any) { await run(async () => { batch.value = await api(`/imports/${row.id}`); batchFilter.value = '全部'; previewPage.value = 1 }) }
async function commitBatch() {
  await run(async () => {
    await ElMessageBox.confirm(`将导入 ${batch.value.counts['可导入']} 条有效数据，错误与重复行将跳过。`, '确认岗位入库', { confirmButtonText: '确认入库', cancelButtonText: '返回检查' }).catch(() => { throw new Error('已取消入库') })
    busy.value = true
    try { batch.value = await api(`/imports/${batch.value.id}/commit`, { method: 'POST' }); await loadBatches(); ElMessage.success('导入完成') } finally { busy.value = false }
  })
}
async function getFile(path: string, name: string) { await run(async () => { await download(path, name) }) }
async function cancelBatch(target: any) {
  busy.value = true
  await run(async () => {
    const canceled = await api(`/imports/${target.id}/cancel`, { method: 'POST' })
    if (batch.value?.id === target.id) batch.value = canceled
    await loadBatches()
    ElMessage.success('导入已取消，校验记录已保留')
  })
  busy.value = false
}
function showStudent(id: number) { studentId.value = id; detailKey.value++; studentDrawer.value = true }
async function editStudent(s: any = null) {
  editingStudent.value = s?.id || null
  studentForm.value = s ? Object.fromEntries(['name', 'phone', 'school', 'education', 'major', 'target_city', 'target_role', 'status', 'notes', 'owner_id'].map(k => [k, s[k]])) : { name: '', phone: '', school: '', education: '本科', major: '', target_city: '', target_role: '', status: '服务中', notes: '', owner_id: me.value.id }
  if (me.value.role === 'admin') await run(async () => { accounts.value = await api('/users') })
  studentDialog.value = true
}
async function saveStudent() {
  if (!studentForm.value.name.trim()) return ElMessage.warning('请填写学员姓名')
  busy.value = true
  await run(async () => {
    const id = editingStudent.value
    await api(id ? `/students/${id}` : '/students', { method: id ? 'PUT' : 'POST', body: JSON.stringify(studentForm.value) })
    studentDialog.value = false; ElMessage.success('学员资料已保存'); if (studentDrawer.value) detailKey.value++; await reload()
  }); busy.value = false
}
async function createAccount() { busy.value = true; await run(async () => { await api('/users', { method: 'POST', body: JSON.stringify(userForm.value) }); userDialog.value = false; userForm.value.password = ''; ElMessage.success('顾问账号已创建'); await reload() }); busy.value = false }
async function toggleAccount(u: any) { await run(async () => { const confirmed = await ElMessageBox.confirm(`${u.active ? '停用' : '启用'}顾问「${u.name}」？该账号的现有登录会话将失效。`, '账号状态', { confirmButtonText: '确认', cancelButtonText: '取消' }).then(() => true).catch(() => false); if (!confirmed) return; await api(`/users/${u.id}`, { method: 'PATCH', body: JSON.stringify({ active: !u.active }) }); await reload() }) }
async function resetPassword() { busy.value = true; await run(async () => { await api(`/users/${passwordUser.value.id}`, { method: 'PATCH', body: JSON.stringify({ password: newPassword.value }) }); newPassword.value = ''; passwordDialog.value = false; ElMessage.success('密码已重置，原会话已撤销') }); busy.value = false }
</script>

<template>
  <div v-if="booting" class="boot-screen">知途 <span>正在连接工作台…</span></div>
  <div v-else-if="!me" class="login-layout">
    <section class="login-story"><div class="brand"><span class="brand-mark">知</span><strong>知途 <small>CAREER DESK</small></strong></div><div class="login-statement"><span class="eyebrow">为每一次职业出发</span><h1>把机会整理好，<br>把陪伴落实好。</h1><p>连接岗位、学员与每一次跟进。<br>让顾问把时间留给真正重要的服务。</p><div class="orbit"><span>岗位</span><i></i><span>学员</span><i></i><span>进展</span></div></div><p class="login-foot">内部求职服务工作台 · MVP 01</p></section>
    <section class="login-form-panel"><form class="login-form" @submit.prevent="login"><span class="eyebrow">WELCOME BACK</span><h2>登录工作台</h2><p>使用管理员分配的内部账号继续工作。</p><label for="username">账号</label><el-input id="username" v-model="loginForm.username" autocomplete="username" size="large" placeholder="请输入账号" maxlength="64" required /><label for="password">密码</label><el-input id="password" v-model="loginForm.password" type="password" show-password autocomplete="current-password" size="large" placeholder="请输入密码" maxlength="128" required /><p v-if="loginError" class="error-text" role="alert">{{ loginError }}</p><el-button class="login-submit" type="primary" size="large" native-type="submit" :loading="busy">进入工作台 <el-icon><ArrowRight /></el-icon></el-button><div class="privacy-note"><el-icon><Lock /></el-icon> 内部使用 · 学员资料按顾问隔离</div></form></section>
  </div>
  <div v-else class="app-layout">
    <aside class="sidebar"><div class="brand"><span class="brand-mark">知</span><strong>知途 <small>CAREER DESK</small></strong></div><span class="nav-caption">工作空间</span><nav><button v-for="n in nav" :key="n.key" :class="{ active: view === n.key }" @click="navigate(n.key)"><el-icon><component :is="n.icon" /></el-icon>{{ n.label }}<span v-if="view === n.key" class="nav-dot"></span></button></nav><template v-if="me.role === 'admin'"><span class="nav-caption">团队管理</span><nav><button :class="{ active: view === 'users' }" @click="navigate('users')"><el-icon><Setting /></el-icon>顾问管理</button><button :class="{ active: view === 'audit' }" @click="navigate('audit')"><el-icon><Tickets /></el-icon>操作日志</button></nav></template><div class="sidebar-bottom"><div class="workspace-note"><span class="live-dot"></span>内部服务工作台<small>共享机会 · 专注服务</small></div><div class="user-block"><div class="avatar">{{ me.name.slice(0, 1) }}</div><div><strong>{{ me.name }}</strong><small>{{ me.role === 'admin' ? '管理员' : '求职顾问' }}</small></div><el-button text aria-label="退出登录" @click="logout"><el-icon><SwitchButton /></el-icon></el-button></div></div></aside>
    <main class="workspace"><header class="topbar"><div><span>知途工作空间</span><span class="divider">/</span><strong>{{ title }}</strong></div><span class="topbar-right"><span class="live-dot"></span>{{ me.role === 'admin' ? '团队管理视角' : '顾问工作空间' }}</span></header>
      <div class="page-content"><div class="page-heading"><div><span class="eyebrow">{{ { dashboard: 'YOUR WORKSPACE', jobs: 'SHARED OPPORTUNITIES', imports: 'DATA INTAKE', students: 'STUDENT SERVICES', users: 'TEAM MEMBERS', audit: 'ACTIVITY LOG' }[view] }}</span><h1>{{ title }}</h1><p>{{ { dashboard: '从清晰的工作安排，开始今天的服务。', jobs: '全团队共享岗位信息，让每一个机会都能被找到。', imports: '先校验，再入库。让岗位数据从源头保持清晰。', students: me.role === 'admin' ? '查看团队学员，分配负责人并持续跟进。' : '管理你负责的学员，留住每一次服务进展。', users: '为顾问分配独立账号，管理团队访问权限。', audit: '追溯关键操作，了解数据如何被访问与更新。' }[view] }}</p></div><div class="heading-actions"><el-button v-if="view === 'jobs'" type="primary" :icon="Upload" @click="navigate('imports')">导入岗位</el-button><el-button v-if="view === 'students'" type="primary" :icon="Plus" @click="editStudent()">新增学员</el-button><el-button v-if="view === 'users'" type="primary" :icon="Plus" @click="userForm = { username: '', name: '', password: '' }; userDialog = true">新增顾问</el-button><el-button :icon="Refresh" aria-label="刷新数据" :loading="loading" @click="reload" /></div></div>
      <div v-loading="loading" class="view-content">
      <template v-if="view === 'dashboard'">
        <div class="metrics"><div v-for="m in [{ label: '共享岗位总数', value: dashboard.jobs, sub: '团队共享资源', icon: Briefcase }, { label: '当前有效岗位', value: dashboard.active_jobs, sub: '可用于学员推荐', icon: CircleCheck }, { label: me.role === 'admin' ? '团队学员' : '我的学员', value: dashboard.students, sub: '持续陪伴每一次求职', icon: User }, { label: '累计岗位推荐', value: dashboard.recommendations, sub: '已保存推荐记录', icon: ArrowRight }]" :key="m.label" class="metric-card"><div class="split"><span>{{ m.label }}</span><el-icon><component :is="m.icon" /></el-icon></div><strong>{{ m.value }}<small>{{ m.label.includes("学员") ? "位" : "条" }}</small></strong><p>{{ m.sub }}</p></div></div>
        <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>待跟进学员 <small>{{ dashboard.reminders.length ? `当前展示 ${dashboard.reminders.length} 条` : '' }}</small></h2><el-tag type="warning" effect="plain">今天及已逾期</el-tag></div><el-table v-if="dashboard.reminders.length" :data="dashboard.reminders"><el-table-column label="学员" prop="student_name" /><el-table-column label="跟进日期" prop="next_date" /><el-table-column label="推荐岗位" min-width="150" show-overflow-tooltip><template #default="{ row }">{{ row.job_snapshot?.title || '普通沟通' }}</template></el-table-column><el-table-column label="最近记录" prop="content" show-overflow-tooltip /><el-table-column width="170"><template #default="{ row }"><el-button text type="primary" @click="showStudent(row.student_id)">去跟进</el-button><el-button text type="success" :loading="handlingFollowup === row.id" :disabled="handlingFollowup !== null" @click="handleReminder(row)">已处理</el-button></template></el-table-column></el-table><el-empty v-else description="暂无到期跟进，服务节奏尽在掌握" :image-size="105" /><p class="panel-foot">以每位学员最新跟进记录中的日期为准，仅展示未处理的到期事件，最多 20 条。</p></section><section class="quick-panel"><span class="eyebrow">START HERE</span><h2>把今天的机会<br>带给合适的学员。</h2><p>从整理岗位开始，<br>到推荐与跟进，形成完整服务记录。</p><button @click="navigate('imports')"><span>01</span>导入一批新岗位<el-icon><ArrowRight /></el-icon></button><button @click="navigate('jobs')"><span>02</span>搜索合适的岗位<el-icon><ArrowRight /></el-icon></button><button @click="navigate('students')"><span>03</span>查看学员与进展<el-icon><ArrowRight /></el-icon></button></section></div>
        <div class="privacy-banner"><el-icon><Lock /></el-icon><div><strong>岗位共享，学员资料独立管理</strong><p>顾问只能访问自己负责的学员；管理员可分配学员并查看团队记录。</p></div><span>访问权限已启用</span></div>
      </template>
      <template v-if="view === 'jobs'">
        <div v-if="recommendationTarget" class="recommend-context"><div>正在为 <strong>{{ recommendationTarget.name }}</strong>（#{{ recommendationTarget.id }}）选择岗位<p>打开岗位详情，即可直接推荐给该学员。</p></div><div><el-button @click="showStudent(recommendationTarget.id)">查看学员档案</el-button><el-button text @click="recommendationTarget = null">退出推荐模式</el-button></div></div>
        <section class="panel filters"><form @submit.prevent="searchJobs"><div class="search-line"><el-input v-model="filters.q" :prefix-icon="Search" placeholder="搜索岗位、公司、专业或岗位描述" clearable /><el-input v-model="filters.city" placeholder="城市，如：上海" clearable /><el-button native-type="submit" type="primary">搜索岗位</el-button><el-button @click="resetFilters">重置</el-button></div><div class="filter-line"><el-select v-model="filters.education" placeholder="学历要求" clearable><el-option v-for="e in educations" :key="e" :label="e" :value="e" /></el-select><el-select v-model="filters.experience" placeholder="经验要求" clearable><el-option v-for="e in experiences" :key="e" :label="e" :value="e" /></el-select><el-select v-model="filters.status" placeholder="全部状态" clearable><el-option label="有效" value="有效" /><el-option label="失效" value="失效" /></el-select><el-input-number v-model="filters.salary_min" :min="0" :controls="false" placeholder="月薪期望下限（元）" /></div></form><p class="hint">学历、经验按要求精确筛选；薪资筛选保留最高月薪达到期望值的岗位；仅有最低月薪时，以最低月薪判断。</p></section>
        <section class="panel"><div class="panel-heading"><h2>岗位列表 <small>{{ jobTotal }} 个岗位</small></h2><span class="hint">同名岗位 + 公司 + 城市识别重复</span></div><el-table :data="jobs" empty-text="暂无岗位，先导入一份 Excel 开始使用" @row-dblclick="showJob"><el-table-column label="岗位 / 公司" min-width="230"><template #default="{ row }"><button class="table-title" @click="showJob(row)">{{ row.title }}</button><div class="table-secondary">{{ row.company }}</div></template></el-table-column><el-table-column prop="city" label="城市" min-width="90" /><el-table-column label="月薪范围" min-width="180"><template #default="{ row }"><span class="salary">{{ salary(row) }}</span></template></el-table-column><el-table-column prop="education" label="学历" width="95" /><el-table-column prop="experience" label="经验" width="100" /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.effective_status === '有效' ? 'success' : 'info'" effect="light">{{ row.effective_status }}</el-tag></template></el-table-column><el-table-column width="80"><template #default="{ row }"><el-button text type="primary" @click="showJob(row)">详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="jobPage" :page-size="20" :total="jobTotal" layout="total, prev, pager, next" @current-change="reload" /></div></section>
      </template>
      <template v-if="view === 'imports'">
        <div class="import-intro"><section class="panel import-upload"><div class="section-head"><h2>导入岗位文件</h2><el-button :icon="Download" @click="getFile('/imports/template', '岗位导入模板.xlsx')">下载模板</el-button></div><div class="import-steps"><span><b>1</b>填写标准模板</span><i></i><span><b>2</b>校验数据预览</span><i></i><span><b>3</b>确认有效岗位入库</span></div><label class="upload-zone" :class="{ disabled: busy }"><el-icon :size="30"><Upload /></el-icon><strong>{{ busy ? '正在处理文件…' : '选择 Excel 文件，开始校验' }}</strong><span>仅支持 .xlsx · 最大 10MB · 每批最多 2,000 行</span><input aria-label="上传岗位 Excel" :disabled="busy" type="file" accept=".xlsx" @change="uploadExcel"></label></section><aside class="import-rules"><span class="eyebrow">QUALITY FIRST</span><h3>每一条岗位，<br>都值得认真整理。</h3><p>必填：岗位名称、公司名称、城市。</p><p>最低、最高月薪均可留空，也可只填一项，单位为人民币元。日期格式：YYYY-MM-DD。</p><p>学历与经验按模板约定值填写，不支持公式，不会覆盖已有岗位。</p><small>学历：{{ educations.join(' / ') }}<br>经验：{{ experiences.join(' / ') }}</small></aside></div>
        <section v-if="batch" class="panel batch-preview"><div class="panel-heading"><h2>校验预览 <small>#{{ batch.id }} · {{ batch.filename }}</small></h2><el-tag :type="batch.status === '已完成' ? 'success' : batch.status === '已取消' ? 'info' : 'warning'">{{ batch.status }}</el-tag></div><div class="batch-stats"><span>共 <strong>{{ batch.total }}</strong> 行</span><span class="success-text">{{ batch.status === '已完成' ? '已导入' : batch.status === '已取消' ? '校验通过' : '可导入' }} <strong>{{ batch.counts[batch.status === '已完成' ? '已导入' : '可导入'] }}</strong></span><span class="error-text">错误 <strong>{{ batch.counts['错误'] }}</strong></span><span>重复 <strong>{{ batch.counts['重复'] }}</strong></span></div><div class="preview-toolbar"><el-radio-group v-model="batchFilter" size="small" @change="previewPage = 1"><el-radio-button v-for="s in ['全部', '可导入', '错误', '重复', '已导入']" :key="s" :value="s">{{ s }}</el-radio-button></el-radio-group><el-button text :icon="Download" @click="getFile(`/imports/${batch.id}/errors`, '岗位导入错误明细.xlsx')">下载错误与重复明细</el-button></div><el-table :data="shownRows" empty-text="此分类没有记录"><el-table-column prop="row_number" label="原始行" width="80" /><el-table-column label="岗位 / 公司" min-width="200"><template #default="{ row }"><strong>{{ row.data.title || '—' }}</strong><div class="table-secondary">{{ row.data.company || '—' }}</div></template></el-table-column><el-table-column label="城市" width="100"><template #default="{ row }">{{ row.data.city || '—' }}</template></el-table-column><el-table-column label="结果" width="100"><template #default="{ row }"><el-tag :type="row.state === '错误' ? 'danger' : row.state === '重复' ? 'warning' : 'success'">{{ row.state }}</el-tag></template></el-table-column><el-table-column label="说明" min-width="240"><template #default="{ row }">{{ row.errors.join('；') || '字段校验通过' }}</template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="previewPage" :page-size="20" :total="previewRows.length" layout="total, prev, pager, next" /></div><div class="import-confirm"><p>{{ batch.status === '已取消' ? '本批次已取消，未写入岗位。校验记录保留，如需导入请重新上传。' : '仅导入通过校验且未重复的行。错误数据请修正后重新上传。' }}</p><div class="import-actions"><template v-if="batch.status === '待确认'"><el-button :disabled="busy" @click="cancelBatch(batch)">取消导入</el-button><el-button type="primary" :loading="busy" :disabled="!batch.counts['可导入']" @click="commitBatch">确认入库 {{ batch.counts['可导入'] }} 条岗位</el-button></template><el-button v-else-if="batch.status === '已完成'" type="success" plain :icon="CircleCheck" @click="navigate('jobs')">查看岗位库</el-button><el-tag v-else type="info">已取消</el-tag></div></div></section>
        <section class="panel"><div class="panel-heading"><h2>导入历史 <small>保留校验与入库结果</small></h2></div><el-table :data="batches" empty-text="还没有导入记录"><el-table-column label="批次" width="80"><template #default="{ row }">#{{ row.id }}</template></el-table-column><el-table-column prop="filename" label="文件名" min-width="200" /><el-table-column prop="total" label="总行数" width="90" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="上传时间" min-width="180"><template #default="{ row }">{{ time(row.created_at) }}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{ row }"><el-button text type="primary" @click="showBatch(row)">查看结果</el-button><el-button v-if="row.status === '待确认'" text :disabled="busy" @click="cancelBatch(row)">取消导入</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="batchPage" :total="batchTotal" :page-size="20" layout="total, prev, pager, next" @current-change="reload" /></div></section>
      </template>
      <template v-if="view === 'students'"><section class="panel"><div class="panel-heading"><h2>{{ me.role === 'admin' ? '团队学员' : '我的学员' }} <small>{{ studentTotal }} 位</small></h2><form class="inline-search" @submit.prevent="run(() => loadStudents(true))"><el-input v-model="studentQ" :prefix-icon="Search" placeholder="搜索姓名、学校、专业或意向岗位" clearable /><el-button native-type="submit">搜索</el-button></form></div><el-table :data="students" empty-text="尚未添加学员，点击「新增学员」建立服务档案"><el-table-column label="学员" min-width="150"><template #default="{ row }"><div class="student-cell"><div class="avatar">{{ row.name.slice(0, 1) }}</div><button class="table-title" @click="showStudent(row.id)">{{ row.name }}</button></div></template></el-table-column><el-table-column prop="education" label="学历" width="100" /><el-table-column prop="school" label="学校" min-width="170" show-overflow-tooltip /><el-table-column prop="major" label="专业" min-width="160" show-overflow-tooltip /><el-table-column prop="target_city" label="意向城市" min-width="110" /><el-table-column prop="target_role" label="意向岗位" min-width="170" show-overflow-tooltip /><el-table-column label="服务状态" width="110"><template #default="{ row }"><el-tag :type="row.status === '服务中' ? 'success' : 'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column width="100"><template #default="{ row }"><el-button text type="primary" @click="showStudent(row.id)">查看档案</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="studentPage" :total="studentTotal" :page-size="20" layout="total, prev, pager, next" @current-change="reload" /></div></section></template>
      <template v-if="view === 'users'"><section class="panel"><div class="panel-heading"><h2>团队账号 <small>{{ accounts.length }} 位成员</small></h2><span class="hint">停用账号会立即撤销其登录会话</span></div><el-table :data="accounts"><el-table-column prop="name" label="姓名" /><el-table-column prop="username" label="账号" /><el-table-column label="角色"><template #default="{ row }">{{ row.role === 'admin' ? '管理员' : '求职顾问' }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><el-tag :type="row.active ? 'success' : 'info'">{{ row.active ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="210"><template #default="{ row }"><template v-if="row.role !== 'admin'"><el-button text type="primary" @click="passwordUser = row; newPassword = ''; passwordDialog = true">重置密码</el-button><el-button text :type="row.active ? 'danger' : 'primary'" @click="toggleAccount(row)">{{ row.active ? '停用' : '启用' }}</el-button></template><span v-else class="hint">服务端维护</span></template></el-table-column></el-table></section></template>
      <template v-if="view === 'audit'"><section class="panel"><div class="panel-heading"><h2>关键操作记录</h2><span class="hint">仅记录操作与对象编号，不记录简历正文或密码</span></div><el-table :data="logs" empty-text="暂无操作日志"><el-table-column prop="user_name" label="操作人" width="130" /><el-table-column prop="action" label="操作" min-width="180" /><el-table-column label="对象" min-width="150"><template #default="{ row }">{{ row.entity }} #{{ row.entity_id }}</template></el-table-column><el-table-column label="时间" min-width="190"><template #default="{ row }">{{ time(row.created_at) }}</template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="logPage" :total="logTotal" :page-size="30" layout="total, prev, pager, next" @current-change="reload" /></div></section></template>
      </div><footer class="page-footer"><span>知途 · 让服务有迹可循</span><span>内部工作台 / MVP 01</span></footer></div>
    </main>
    <el-drawer v-model="jobDrawer" :title="jobEditing ? '编辑岗位' : '岗位详情'" size="min(700px, 96vw)" destroy-on-close><template v-if="selectedJob"><template v-if="!jobEditing"><div class="job-detail-heading"><el-tag :type="selectedJob.effective_status === '有效' ? 'success' : 'info'">{{ selectedJob.effective_status }}</el-tag><h2>{{ selectedJob.title }}</h2><p>{{ selectedJob.company }} · {{ selectedJob.city }}</p><strong class="salary">{{ salary(selectedJob) }}</strong></div><div class="info-grid"><div><label>学历要求</label><p>{{ selectedJob.education }}</p></div><div><label>经验要求</label><p>{{ selectedJob.experience }}</p></div><div><label>专业要求</label><p>{{ selectedJob.major || '未填写' }}</p></div><div><label>截止日期</label><p>{{ selectedJob.expires_on || '未填写' }}</p></div></div><h3>岗位描述</h3><p class="description-text">{{ selectedJob.description || '暂无岗位描述，建议补充后再推荐。' }}</p><h3>信息来源</h3><p class="note-text">{{ selectedJob.source || '未填写' }}</p><p class="hint">入库时间：{{ time(selectedJob.created_at) }}</p><div class="drawer-actions"><el-button type="primary" @click="editJob">编辑岗位</el-button><el-button type="primary" plain :disabled="selectedJob.effective_status !== '有效'" @click="recommendDialog = true">{{ recommendationTarget ? `推荐给${recommendationTarget.name}` : '推荐给学员' }}</el-button></div></template><el-form v-else label-position="top" @submit.prevent="saveJob"><el-form-item label="岗位名称" required><el-input v-model="jobForm.title" maxlength="160" /></el-form-item><el-form-item label="公司名称" required><el-input v-model="jobForm.company" maxlength="160" /></el-form-item><div class="form-grid"><el-form-item label="城市" required><el-input v-model="jobForm.city" maxlength="80" /></el-form-item><el-form-item label="状态"><el-select v-model="jobForm.status"><el-option value="有效" /><el-option value="失效" /></el-select></el-form-item><el-form-item label="学历"><el-select v-model="jobForm.education"><el-option v-for="e in educations" :key="e" :value="e" /></el-select></el-form-item><el-form-item label="经验"><el-select v-model="jobForm.experience"><el-option v-for="e in experiences" :key="e" :value="e" /></el-select></el-form-item><el-form-item label="最低月薪（元）"><el-input-number v-model="jobForm.salary_min" :min="0" :max="1000000" :controls="false" /></el-form-item><el-form-item label="最高月薪（元）"><el-input-number v-model="jobForm.salary_max" :min="0" :max="1000000" :controls="false" /></el-form-item></div><el-form-item label="专业要求"><el-input v-model="jobForm.major" maxlength="200" /></el-form-item><el-form-item label="岗位描述"><el-input v-model="jobForm.description" type="textarea" :rows="8" maxlength="10000" /></el-form-item><el-form-item label="来源"><el-input v-model="jobForm.source" maxlength="300" /></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="jobForm.expires_on" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-button type="primary" native-type="submit" :loading="busy">保存岗位</el-button><el-button @click="jobEditing = false">取消</el-button></el-form></template></el-drawer>
    <el-drawer v-model="studentDrawer" title="学员服务档案" size="min(780px, 96vw)" destroy-on-close><StudentDetail v-if="studentDrawer" :key="detailKey" :student-id="studentId" @edit="editStudent" @changed="reload" @browse-jobs="browseJobsForStudent" /></el-drawer>
    <RecommendDialog v-model="recommendDialog" :job="selectedJob" :initial-student="recommendationTarget" @recommended="recommendationSaved" />
    <el-dialog v-model="studentDialog" :title="editingStudent ? '编辑学员资料' : '新增学员'" width="640px" destroy-on-close><el-form label-position="top" @submit.prevent="saveStudent"><div class="form-grid"><el-form-item label="姓名" required><el-input v-model="studentForm.name" maxlength="80" /></el-form-item><el-form-item label="联系电话"><el-input v-model="studentForm.phone" maxlength="40" /></el-form-item><el-form-item label="学历"><el-select v-model="studentForm.education"><el-option v-for="e in educations" :key="e" :value="e" /></el-select></el-form-item><el-form-item label="学校"><el-input v-model="studentForm.school" maxlength="200" placeholder="如：某某大学" /></el-form-item><el-form-item label="专业"><el-input v-model="studentForm.major" maxlength="200" /></el-form-item><el-form-item label="意向城市"><el-input v-model="studentForm.target_city" maxlength="100" /></el-form-item><el-form-item label="意向岗位"><el-input v-model="studentForm.target_role" maxlength="200" /></el-form-item><el-form-item label="服务状态"><el-select v-model="studentForm.status"><el-option v-for="s in ['服务中', '已入职', '已结束']" :key="s" :value="s" /></el-select></el-form-item><el-form-item v-if="me.role === 'admin'" label="负责顾问"><el-select v-model="studentForm.owner_id"><el-option v-for="a in accounts.filter(a => a.active)" :key="a.id" :value="a.id" :label="a.name" /></el-select></el-form-item></div><el-alert v-if="editingStudent && me.role === 'admin'" title="转交负责人后，原顾问将失去该学员及其简历、推荐和跟进记录的访问权限。" type="info" :closable="false" /><el-form-item label="备注"><el-input v-model="studentForm.notes" type="textarea" :rows="3" maxlength="10000" /></el-form-item></el-form><template #footer><el-button @click="studentDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveStudent">保存资料</el-button></template></el-dialog>
    <el-dialog v-model="userDialog" title="新增顾问账号" width="460px"><el-form label-position="top"><el-form-item label="姓名"><el-input v-model="userForm.name" maxlength="80" /></el-form-item><el-form-item label="账号（3～64 位字母、数字、点、横线或下划线）"><el-input v-model="userForm.username" autocomplete="off" maxlength="64" /></el-form-item><el-form-item label="初始密码（至少 10 位）"><el-input v-model="userForm.password" type="password" show-password autocomplete="new-password" maxlength="128" /></el-form-item></el-form><template #footer><el-button @click="userDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="createAccount">创建账号</el-button></template></el-dialog>
    <el-dialog v-model="passwordDialog" title="重置顾问密码" width="460px"><p>账号：{{ passwordUser?.name }}（{{ passwordUser?.username }}）</p><el-input v-model="newPassword" aria-label="新密码" type="password" show-password placeholder="新密码，至少 10 位" autocomplete="new-password" maxlength="128" /><template #footer><el-button @click="passwordDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="resetPassword">确认重置</el-button></template></el-dialog>
  </div>
</template>
